def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    objs = objects(g, bg=bg)
    for o in objs:
        cells = set(o["cells"])
        branch = False
        corners = 0
        for (y, x) in cells:
            h = ((y, x - 1) in cells) + ((y, x + 1) in cells)
            v = ((y - 1, x) in cells) + ((y + 1, x) in cells)
            if h + v >= 3:
                branch = True
            if h == 1 and v == 1:
                corners += 1
        if branch:
            col, why = 2, "has a T-junction (branch cell)"
        elif corners >= 2:
            col, why = 6, "is a simple path with two bends"
        else:
            col, why = 1, "is a simple L with one bend"
        for (y, x) in cells:
            out[y, x] = col
        emit(out, f"Object at box {o['box']} {why}, so it is recoloured to {col}.")
    emit(out, "All objects recoloured by shape type: final grid.")
    return out
